const raw = $input.first().json;
const score = Array.isArray(raw) ? raw[0] : raw;

if (!score || !score.run_date_sgt) {
  return [{ json: { subject: 'Daily Market Risk Briefing - No Data', emailBody: 'No daily signal score was found.', telegramText: 'No daily signal score was found.' } }];
}

const fmt = (v) => v === null || v === undefined || v === '' ? 'N/A' : v;

const risk = Number(score.overall_risk_score);
const label = fmt(score.signal_label);
const bias = fmt(score.action_bias);

let tone = 'Market conditions are broadly balanced.';
if (risk >= 75) tone = 'Market risk is at an extreme level. The system favours a defensive stance.';
else if (risk >= 60) tone = 'Market risk is elevated. The system favours reducing risk and monitoring downside triggers.';
else if (risk >= 40) tone = 'Market risk is in watch mode. Conditions are not alarming, but several drivers require monitoring.';
else tone = 'Market risk is normal. The system does not currently detect broad stress.';

const drivers = [
  `Valuation: ${fmt(score.valuation_score)}/100`,
  `Macro: ${fmt(score.macro_score)}/100`,
  `Market Stress: ${fmt(score.stress_score)}/100`,
  `Momentum: ${fmt(score.momentum_score)}/100`,
  `Sentiment: ${fmt(score.sentiment_score)}/100`
];

const watchlist = [
  'VIX moving above 20',
  'SPY or QQQ weakening below the 200-day moving average',
  'US 10Y yield rising sharply over 20 trading days',
  'Forward P/E expanding while momentum weakens',
  'Risk score crossing 60 or 75 thresholds'
];

const subject = `Daily Market Risk Briefing - ${score.run_date_sgt}`;

const emailBody = `
<h2>Daily Market Risk Briefing</h2>
<p><b>Date:</b> ${score.run_date_sgt}</p>
<p><b>Overall Signal:</b> ${label}</p>
<p><b>Risk Score:</b> ${fmt(score.overall_risk_score)} / 100</p>
<p><b>Action Bias:</b> ${bias}</p>

<h3>1. Main Signal</h3>
<p>${tone}</p>

<h3>2. Signal Drivers</h3>
<ul>
  ${drivers.map(d => `<li>${d}</li>`).join('\n')}
</ul>

<h3>3. Key Evidence</h3>
<p>${fmt(score.key_drivers)}</p>

<h3>4. Watchlist</h3>
<ul>
  ${watchlist.map(w => `<li>${w}</li>`).join('\n')}
</ul>

<p><i>Generated automatically by the Decision-Grade Market Risk Signal System.</i></p>
`.trim();

const telegramText = `📊 <b>Daily Market Risk Briefing</b>\n\n` +
`<b>Date:</b> ${score.run_date_sgt}\n` +
`<b>Overall Signal:</b> ${label}\n` +
`<b>Risk Score:</b> ${fmt(score.overall_risk_score)} / 100\n` +
`<b>Action Bias:</b> ${bias}\n\n` +
`<b>1. Main Signal</b>\n${tone}\n\n` +
`<b>2. Signal Drivers</b>\n` +
`${drivers.map(d => `• ${d}`).join('\n')}\n\n` +
`<b>3. Key Evidence</b>\n${fmt(score.key_drivers)}\n\n` +
`<b>4. Watchlist</b>\n` +
`${watchlist.map(w => `• ${w}`).join('\n')}`;

return [{
  json: {
    subject,
    emailBody,
    telegramText,
    run_date_sgt: score.run_date_sgt,
    overall_risk_score: score.overall_risk_score,
    signal_label: score.signal_label,
    action_bias: score.action_bias
  }
}];
